defmodule Solution do def two_sum(numbers, target), do: search(numbers, target, List.last(numbers), 1, nil); defp search([], _, _, _, _), do: []; defp search([value | rest], target, maximum, index, previous) do wanted = target - value; cond do wanted < value -> []; value == previous or wanted > maximum -> search(rest, target, maximum, index + 1, value); true -> case locate(rest, wanted, index + 1) do nil -> search(rest, target, maximum, index + 1, value); other -> [index, other] end end end; defp locate([], _, _), do: nil; defp locate([value | _], wanted, index) when value == wanted, do: index; defp locate([value | _], wanted, _) when value > wanted, do: nil; defp locate([_ | rest], wanted, index), do: locate(rest, wanted, index + 1) end
